export class AppComponent {
  readonly slides: Slide[] = [
    {
      id: 1,
      title: 'Snowflakes glowing under city lights',
      imageUrl: 'https://picsum.photos/seed/slide-1/800/400'
    },
    {
      id: 2,
      title: 'Forest trail in the morning',
      imageUrl: 'https://images.pexels.com/photos/1563604/pexels-photo-1563604.jpeg'
    },
    {
      id: 3,
      title: 'City lights at night',
      imageUrl: 'https://images.pexels.com/photos/220067/pexels-photo-220067.jpeg'
    }
  ];
  readonly totalSlides = this.slides.length;

  readonly currentIndex = signal(0);
  readonly currentSlide = computed(() => this.slides[this.currentIndex()] ?? null);
  readonly canGoPrev = computed(() => this.currentIndex() > 0);
  readonly canGoNext = computed(() => this.currentIndex() < this.totalSlides - 1);

  goTo(index: number): void {
    if (index < 0 || index >= this.totalSlides) {
      return;
    }
    this.currentIndex.set(index);
  }

  prev(): void {
    if (this.canGoPrev()) {
      this.currentIndex.update((index) => index - 1);
    }
  }

  next(): void {
    if (this.canGoNext()) {
      this.currentIndex.update((index) => index + 1);
    }
  }
}

