import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';
import { TitleCasePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';

interface User {
  id: number;
  name: string;
  role: Role;
  active: boolean;
}

type Role = 'admin' | 'editor' | 'viewer';

type RoleFilter = 'all' | Role;

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, TitleCasePipe],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly searchTerm = signal('');
  readonly selectedRole = signal<RoleFilter>('all');
  readonly showOnlyActive = signal(false);

  readonly users: User[] = [
    { id: 1, name: 'Alice Johnson', role: 'admin', active: true },
    { id: 2, name: 'Bob Smith', role: 'editor', active: false },
    { id: 3, name: 'Charlie Kim', role: 'viewer', active: true },
    { id: 4, name: 'Dana Patel', role: 'editor', active: true },
    { id: 5, name: 'Elliot Brown', role: 'viewer', active: false }
  ];

  readonly filteredUsers = computed(() => {
    const term = this.searchTerm().trim().toLowerCase();
    const role = this.selectedRole();
    const onlyActive = this.showOnlyActive();

    return this.users.filter((user) => {
      if (term && !user.name.toLowerCase().includes(term)) {
        return false;
      }

      if (role !== 'all' && user.role !== role) {
        return false;
      }

      if (onlyActive && !user.active) {
        return false;
      }

      return true;
    });
  });
}

