import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { AbstractControl, FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { map } from 'rxjs';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ReactiveFormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export default class AppComponent {
  readonly lastStepIndex = 2;
  readonly currentStep = signal(0);
  readonly submitMessage = signal('');
  readonly isFirstStep = computed(() => this.currentStep() === 0);
  readonly isLastStep = computed(() => this.currentStep() === this.lastStepIndex);

  private readonly fb = inject(FormBuilder);

  readonly form = this.fb.group({
    basic: this.fb.group({
      name: ['', Validators.required],
      email: ['', [Validators.required, Validators.email]]
    }),
    address: this.fb.group({
      street: ['', Validators.required],
      city: ['', Validators.required],
      country: ['', Validators.required],
      postalCode: ['']
    })
  });
  readonly basicGroup = this.form.controls.basic;
  readonly addressGroup = this.form.controls.address;

  // A group's validity is not a signal; statusChanges makes it one, so canGoNext follows the user's typing.
  private readonly basicValid = toSignal(
    this.basicGroup.statusChanges.pipe(map((status) => status === 'VALID')),
    { initialValue: this.basicGroup.valid }
  );
  private readonly addressValid = toSignal(
    this.addressGroup.statusChanges.pipe(map((status) => status === 'VALID')),
    { initialValue: this.addressGroup.valid }
  );

  readonly canGoNext = computed(() => {
    const step = this.currentStep();
    if (step === 0) {
      return this.basicValid();
    }
    if (step === 1) {
      return this.addressValid();
    }
    return false;
  });

  private currentGroup(): AbstractControl {
    const step = this.currentStep();
    if (step === 0) {
      return this.basicGroup;
    }
    if (step === 1) {
      return this.addressGroup;
    }
    return this.form;
  }

  next(): void {
    this.submitMessage.set('');
    const group = this.currentGroup();
    group.markAllAsTouched();
    if (group.invalid) {
      return;
    }
    if (!this.isLastStep()) {
      this.currentStep.update((step) => step + 1);
    }
  }

  prev(): void {
    this.submitMessage.set('');
    if (!this.isFirstStep()) {
      this.currentStep.update((step) => step - 1);
    }
  }

  submit(): void {
    this.submitMessage.set('');
    this.form.markAllAsTouched();
    if (this.form.invalid) {
      return;
    }
    console.log('Signup submitted', this.form.value);
    this.submitMessage.set('Signup submitted! Check the console for payload.');
  }
}

