import { ChangeDetectionStrategy, Component, ElementRef, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

type Candidate = {
  id: string;
  name: string;
  email: string;
};

type Chip = {
  id: string;
  label: string;
  value: string;
};

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css'],
  host: {
    '(document:mousedown)': 'onDocMouseDown($event)'
  }
})
export class AppComponent {
  private readonly host = inject(ElementRef<HTMLElement>);

  readonly listboxId = 'invite-suggestions';

  readonly users: Candidate[] = [
    { id: 'alice', name: 'Alice Johnson', email: 'alice@frontendatlas.dev' },
    { id: 'bob', name: 'Bob Smith', email: 'bob@frontendatlas.dev' },
    { id: 'charlie', name: 'Charlie Kim', email: 'charlie@frontendatlas.dev' },
    { id: 'diana', name: 'Diana Lopez', email: 'diana@frontendatlas.dev' },
    { id: 'ethan', name: 'Ethan Brown', email: 'ethan@frontendatlas.dev' },
    { id: 'fiona', name: 'Fiona Patel', email: 'fiona@frontendatlas.dev' },
    { id: 'george', name: 'George Miller', email: 'george@frontendatlas.dev' }
  ];

  readonly chips = signal<Chip[]>([]);
  readonly query = signal('');
  readonly isOpen = signal(false);
  readonly activeIndex = signal(-1);

  // Recomputed only when query() or chips() change, so the template and handleKeyDown share one list.
  readonly suggestions = computed<Chip[]>(() => {
    const needle = this.normalize(this.query());
    if (!needle) return [];

    const selectedIds = new Set(this.chips().map((chip) => chip.id));

    return this.users
      .filter((user) => {
        if (selectedIds.has(user.id)) return false;
        const haystack = (user.name + ' ' + user.email).toLowerCase();
        return haystack.includes(needle);
      })
      .slice(0, 6)
      .map((user) => ({
        id: user.id,
        label: user.name,
        value: user.email
      }));
  });

  readonly activeDescendant = computed(() => {
    const index = this.activeIndex();
    return index >= 0 ? this.optionId(index) : null;
  });

  onInput(value: string): void {
    this.query.set(value);
    this.activeIndex.set(-1);
    this.syncOpenState();
  }

  onFocus(): void {
    this.syncOpenState();
  }

  addChip(chip: Chip): void {
    const hasDuplicate = this.chips().some(
      (item) => item.id === chip.id || this.normalize(item.value) === this.normalize(chip.value)
    );
    if (!hasDuplicate) {
      this.chips.update((chips) => [...chips, chip]);
    }

    this.query.set('');
    this.isOpen.set(false);
    this.activeIndex.set(-1);
  }

  addCustomFromQuery(): void {
    const raw = this.query().trim();
    if (!raw) return;

    this.addChip({
      id: 'custom-' + this.normalize(raw),
      label: raw,
      value: raw
    });
  }

  removeChip(chipId: string): void {
    this.chips.update((chips) => chips.filter((chip) => chip.id !== chipId));
    this.syncOpenState();
  }

  selectSuggestion(chip: Chip): void {
    this.addChip(chip);
  }

  handleKeyDown(event: KeyboardEvent): void {
    const suggestions = this.suggestions();
    const len = suggestions.length;

    if (event.key === 'ArrowDown') {
      event.preventDefault();
      if (!len) return;
      this.isOpen.set(true);
      this.activeIndex.update((index) => (index < 0 ? 0 : (index + 1) % len));
      return;
    }

    if (event.key === 'ArrowUp') {
      event.preventDefault();
      if (!len) return;
      this.isOpen.set(true);
      this.activeIndex.update((index) => (index < 0 ? len - 1 : (index - 1 + len) % len));
      return;
    }

    if (event.key === 'Enter') {
      event.preventDefault();
      const index = this.activeIndex();
      if (this.isOpen() && index >= 0 && index < len) {
        this.addChip(suggestions[index]);
      } else {
        this.addCustomFromQuery();
      }
      return;
    }

    if (event.key === ',') {
      event.preventDefault();
      this.addCustomFromQuery();
      return;
    }

    if (event.key === 'Backspace' && !this.query() && this.chips().length > 0) {
      this.chips.update((chips) => chips.slice(0, -1));
      this.syncOpenState();
      return;
    }

    if (event.key === 'Escape') {
      this.isOpen.set(false);
      this.activeIndex.set(-1);
    }
  }

  optionId(index: number): string {
    return 'invite-option-' + String(index);
  }

  onDocMouseDown(event: MouseEvent): void {
    const target = event.target as Node | null;
    if (!target) return;
    if (!this.host.nativeElement.contains(target)) {
      this.isOpen.set(false);
      this.activeIndex.set(-1);
    }
  }

  private syncOpenState(): void {
    const hasQuery = this.normalize(this.query()).length > 0;
    const open = hasQuery && this.suggestions().length > 0;
    this.isOpen.set(open);
    if (!open) {
      this.activeIndex.set(-1);
    }
  }

  private normalize(value: string): string {
    return value.trim().toLowerCase();
  }
}

