@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly minSize = 2;
  readonly maxSize = 20;

  readonly size = signal(8);
  readonly selectedKey = signal<string | null>(null);

  readonly rows = computed(() => Array.from({ length: this.size() }, (_, index) => index));
  readonly selectedLabel = computed(() => {
    const key = this.selectedKey();
    if (!key) return 'Selected: none';
    const [row, col] = key.split('-').map(Number);
    return 'Selected: row ' + String(row + 1) + ', column ' + String(col + 1);
  });

  // Bound to (change), which fires on Enter, on blur and on the arrows, so 12 can be typed through 1.
  onSizeChange(input: HTMLInputElement): void {
    const raw = input.value.trim();
    const next = raw === '' ? Number.NaN : Number(raw);
    const size = Number.isFinite(next)
      ? Math.max(this.minSize, Math.min(this.maxSize, Math.trunc(next)))
      : this.size();
    // [value] writes the field only when size() changes, so a value clamped to the current size is put back here.
    input.value = String(size);
    if (size === this.size()) return;
    this.size.set(size);
    this.selectedKey.set(null);
  }

  onCellClick(row: number, col: number): void {
    this.selectedKey.set(this.cellKey(row, col));
  }

  cellKey(row: number, col: number): string {
    return String(row) + '-' + String(col);
  }

  // Per cell, so a method rather than a computed; Angular still tracks the selectedKey() read.
  cellClass(row: number, col: number): string {
    const dark = (row + col) % 2 === 1;
    const active = this.selectedKey() === this.cellKey(row, col);
    return 'cell ' + (dark ? 'cell--dark' : 'cell--light') + (active ? ' cell--active' : '');
  }
}

// src/app/snake-engine.ts
export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';
export type Point = { x: number; y: number };

export interface SnakeSnapshot {
  snake: Point[];
  direction: Direction;
  bufferedDirection: Direction | null;
  food: Point | null;
  score: number;
}

export interface SnakeStep extends SnakeSnapshot {
  outcome: 'moved' | 'lost' | 'won';
}

const DELTA: Record<Direction, Point> = {
  UP: { x: 0, y: -1 },
  DOWN: { x: 0, y: 1 },
  LEFT: { x: -1, y: 0 },
  RIGHT: { x: 1, y: 0 }
};

const OPPOSITE: Record<Direction, Direction> = {
  UP: 'DOWN',
  DOWN: 'UP',
  LEFT: 'RIGHT',
  RIGHT: 'LEFT'
};

function key(point: Point): string {
  return String(point.x) + ',' + String(point.y);
}

export function bufferTurn(
  committed: Direction,
  buffered: Direction | null,
  requested: Direction
): Direction | null {
  if (buffered !== null) return buffered;
  if (requested === committed || OPPOSITE[committed] === requested) return null;
  return requested;
}

export function placeFood(
  snake: Point[],
  boardSize: number,
  random: () => number = Math.random
): Point | null {
  const occupied = new Set(snake.map(key));
  const free: Point[] = [];

  for (let y = 0; y < boardSize; y += 1) {
    for (let x = 0; x < boardSize; x += 1) {
      const point = { x, y };
      if (!occupied.has(key(point))) free.push(point);
    }
  }

  if (free.length === 0) return null;
  const index = Math.min(free.length - 1, Math.floor(random() * free.length));
  return free[index];
}

export function stepSnake(
  state: SnakeSnapshot,
  boardSize: number,
  random: () => number = Math.random
): SnakeStep {
  const direction = state.bufferedDirection ?? state.direction;
  const delta = DELTA[direction];
  const head = state.snake[0];
  const nextHead = { x: head.x + delta.x, y: head.y + delta.y };
  const base = { ...state, direction, bufferedDirection: null };

  if (
    nextHead.x < 0 ||
    nextHead.y < 0 ||
    nextHead.x >= boardSize ||
    nextHead.y >= boardSize
  ) {
    return { ...base, outcome: 'lost' };
  }

  const ateFood = state.food !== null && key(nextHead) === key(state.food);
  const collisionBody = ateFood ? state.snake : state.snake.slice(0, -1);
  if (collisionBody.some((part) => key(part) === key(nextHead))) {
    return { ...base, outcome: 'lost' };
  }

  const snake = [nextHead, ...state.snake];
  if (!ateFood) {
    snake.pop();
    return { ...base, snake, outcome: 'moved' };
  }

  const food = placeFood(snake, boardSize, random);
  return {
    ...base,
    snake,
    food,
    score: state.score + 1,
    outcome: food === null ? 'won' : 'moved'
  };
}

// src/app/app.component.ts
import { ChangeDetectionStrategy, Component, DestroyRef, computed, inject, signal } from '@angular/core';
import {
  bufferTurn,
  stepSnake,
  type Direction,
  type Point
} from './snake-engine';

const BOARD_SIZE = 14;
const STEP_MS = 140;
const INITIAL_SNAKE: Point[] = [
  { x: 6, y: 7 },
  { x: 5, y: 7 },
  { x: 4, y: 7 }
];
const INITIAL_FOOD: Point = { x: 8, y: 7 };

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '(window:keydown)': 'onKeydown($event)' },
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly boardSize = BOARD_SIZE;
  readonly boardIndices = Array.from({ length: BOARD_SIZE }, (_, index) => index);

  readonly snake = signal<Point[]>(INITIAL_SNAKE.map((point) => ({ ...point })));
  readonly direction = signal<Direction>('RIGHT');
  readonly bufferedDirection = signal<Direction | null>(null);
  readonly food = signal<Point | null>({ ...INITIAL_FOOD });
  readonly isRunning = signal(false);
  readonly isGameOver = signal(false);
  readonly isWon = signal(false);
  readonly score = signal(0);

  readonly length = computed(() => this.snake().length);
  readonly statusLabel = computed(() => {
    if (this.isWon()) return 'You win';
    if (this.isGameOver()) return 'Game over';
    return this.isRunning() ? 'Running' : 'Paused';
  });

  private timerId: ReturnType<typeof setInterval> | null = null;

  constructor() {
    inject(DestroyRef).onDestroy(() => this.clearTimer());
  }

  onKeydown(event: KeyboardEvent): void {
    const key = String(event.key || '').toLowerCase();

    if (key === ' ') {
      event.preventDefault();
      if (!this.isGameOver() && !this.isWon()) this.toggleRunning();
      return;
    }

    if (key === 'enter' && (this.isGameOver() || this.isWon())) {
      event.preventDefault();
      this.reset();
      return;
    }

    const requested = this.directionFromKey(key);
    if (!requested) return;

    event.preventDefault();
    this.bufferedDirection.set(bufferTurn(this.direction(), this.bufferedDirection(), requested));
  }

  toggleRunning(): void {
    if (this.isGameOver() || this.isWon()) return;
    this.isRunning() ? this.pause() : this.start();
  }

  start(): void {
    if (this.isRunning() || this.isGameOver() || this.isWon()) return;
    this.isRunning.set(true);
    this.clearTimer();
    this.timerId = setInterval(() => this.tick(), STEP_MS);
  }

  pause(): void {
    this.isRunning.set(false);
    this.clearTimer();
  }

  reset(): void {
    this.clearTimer();
    this.snake.set(INITIAL_SNAKE.map((point) => ({ ...point })));
    this.direction.set('RIGHT');
    this.bufferedDirection.set(null);
    this.food.set({ ...INITIAL_FOOD });
    this.isRunning.set(false);
    this.isGameOver.set(false);
    this.isWon.set(false);
    this.score.set(0);
  }

  isSnake(x: number, y: number): boolean {
    return this.snake().some((point) => point.x === x && point.y === y);
  }

  isHead(x: number, y: number): boolean {
    const head = this.snake()[0];
    return head.x === x && head.y === y;
  }

  isFood(x: number, y: number): boolean {
    const food = this.food();
    return food !== null && food.x === x && food.y === y;
  }

  private tick(): void {
    if (!this.isRunning() || this.isGameOver() || this.isWon()) return;

    const result = stepSnake({
      snake: this.snake(),
      direction: this.direction(),
      bufferedDirection: this.bufferedDirection(),
      food: this.food(),
      score: this.score()
    }, this.boardSize);

    // stepSnake builds a new array for every move; editing the current array in place would not notify the signal.
    this.snake.set(result.snake);
    this.direction.set(result.direction);
    this.bufferedDirection.set(result.bufferedDirection);
    this.food.set(result.food);
    this.score.set(result.score);

    if (result.outcome === 'lost') {
      this.isGameOver.set(true);
      this.pause();
    } else if (result.outcome === 'won') {
      this.isWon.set(true);
      this.pause();
    }
  }

  private directionFromKey(key: string): Direction | null {
    if (key === 'arrowup' || key === 'w') return 'UP';
    if (key === 'arrowdown' || key === 's') return 'DOWN';
    if (key === 'arrowleft' || key === 'a') return 'LEFT';
    if (key === 'arrowright' || key === 'd') return 'RIGHT';
    return null;
  }

  private clearTimer(): void {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
  }
}

